```cpp
#include<iostream>
#include<vector>
#include<string>
#include<unordered_map>
#include<algorithm>
using namespace std;

bool check(vector<string> v1,vector<string> v2){
    int m=v1.size(),n=v2.size();
    if(m!=n){
        return false;
    }
    for(int i=0;i<m;i++){
        if(v1[i]!=v2[i]){
            return false;
        }
    }
    //完全相同则返回true
    return true;
}

int main(){
    int q,op;
    string s;
    cin>>q;
    unordered_map<string,unordered_map<string,vector<vector<string>>>> ump;
    while(q--){
        cin>>op;
        cin.get();
        getline(cin,s);
        int pos=s.find('(');
        string s1=s.substr(0,pos),s2=s.substr(pos);//函数名，参数列表
        int l=s2.size(),pre=0;//逗号坐标
        vector<string> tmp;
        //调用
        if(s1.find(' ')==string::npos){
            for(int i=0;i<l;i++){
                if(s2[i]==','||s2[i]==')'){
                    string ss2=s2.substr(pre+1,i-pre-1);
                    tmp.push_back(ss2);
                    pre=i;
                }
            }
            if(!ump.count(s1)){
                cout<<"There is no function "<<s1<<"."<<endl;
            }
            else{
                bool flag=false;
                for(auto& p:ump[s1]){
                    for(auto& q:p.second){
                        if(check(q,tmp)){
                            flag=true;
                            cout<<"Yes."<<endl;
                            break;
                        }
                    }
                    if(flag){
                        break;
                    }
                }
                if(!flag){
                    cout<<s1<<" was not declared in this scope."<<endl;
                }
            }
        }
        //重载
        else{
            int p=s1.find(' ');
            string ss1=s1.substr(0,p),ss2=s1.substr(p+1);//返回值类型，函数名
            for(int i=0;i<l;i++){
                if(s2[i]==' '){
                    string ss2=s2.substr(pre+1,i-pre-1);
                    tmp.push_back(ss2);
                }
                else if(s2[i]==','){
                    pre=i;
                }
            }
            bool flag=false;
            if(ump.count(ss2)){
                for(auto& p:ump[ss2]){
                    for(auto& q:p.second){
                        if(check(q,tmp)){
                            flag=true;
                            cout<<"redefinition of "<<ss2<<"."<<endl;
                            break;
                        }
                    }
                    if(flag){
                        break;
                    }
                }
            }
            if(!flag){
                cout<<"Yes."<<endl;
            }
            ump[ss2][ss1].push_back(tmp);
        }
    }
    return 0;
}
